"""Trie (prefix tree) with insert, search, starts_with, delete, and autocomplete."""

from __future__ import annotations


class _Node:
    __slots__ = ("children", "is_end", "count")

    def __init__(self) -> None:
        self.children: dict[str, _Node] = {}
        self.is_end: bool = False
        self.count: int = 0  # number of words ending at this node


class Trie:
    __slots__ = ("_root", "_size")

    def __init__(self) -> None:
        self._root = _Node()
        self._size = 0

    # ------------------------------------------------------------------
    # Core operations
    # ------------------------------------------------------------------

    def insert(self, word: str) -> None:
        """Insert *word* into the trie.  Duplicate inserts are idempotent."""
        node = self._root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = _Node()
            node = node.children[ch]
        if not node.is_end:
            node.is_end = True
            self._size += 1
        node.count += 1

    def search(self, word: str) -> bool:
        """Return ``True`` if *word* exists in the trie."""
        node = self._find(word)
        return node is not None and node.is_end

    def starts_with(self, prefix: str) -> bool:
        """Return ``True`` if any word in the trie starts with *prefix*."""
        return self._find(prefix) is not None

    def delete(self, word: str) -> bool:
        """Remove one occurrence of *word*.  Returns ``True`` if it existed."""
        node = self._root
        path: list[tuple[_Node, str]] = []  # (parent, char) pairs

        for ch in word:
            if ch not in node.children:
                return False
            path.append((node, ch))
            node = node.children[ch]

        if not node.is_end:
            return False

        node.count -= 1
        if node.count == 0:
            node.is_end = False
            self._size -= 1

            # Prune empty leaf nodes bottom-up.
            for parent, ch in reversed(path):
                child = parent.children[ch]
                if not child.is_end and not child.children:
                    del parent.children[ch]
                else:
                    break

        return True

    def autocomplete(self, prefix: str, limit: int = 10) -> list[str]:
        """Return up to *limit* words that start with *prefix*."""
        node = self._find(prefix)
        if node is None:
            return []
        results: list[str] = []
        self._collect(node, prefix, results, limit)
        return results

    # ------------------------------------------------------------------
    # Dunders & helpers
    # ------------------------------------------------------------------

    def __contains__(self, word: str) -> bool:
        return self.search(word)

    def __len__(self) -> int:
        return self._size

    def __bool__(self) -> bool:
        return self._size > 0

    def _find(self, prefix: str) -> _Node | None:
        node = self._root
        for ch in prefix:
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node

    def _collect(
        self,
        node: _Node,
        prefix: str,
        out: list[str],
        limit: int,
    ) -> None:
        if len(out) >= limit:
            return
        if node.is_end:
            out.append(prefix)
        for ch in sorted(node.children):
            self._collect(node.children[ch], prefix + ch, out, limit)


if __name__ == "__main__":
    t = Trie()
    for w in ("apple", "app", "apt", "bat", "ball", "band"):
        t.insert(w)

    print("search 'app':", t.search("app"))       # True
    print("search 'ap':", t.search("ap"))          # False
    print("starts_with 'ap':", t.starts_with("ap"))  # True
    print("autocomplete 'ap':", t.autocomplete("ap"))  # ['app', 'apple', 'apt']
    print("autocomplete 'ba':", t.autocomplete("ba"))  # ['ball', 'band', 'bat']

    t.delete("app")
    print("after delete 'app':", t.search("app"))  # False
    print("autocomplete 'ap':", t.autocomplete("ap"))  # ['apple', 'apt']
    print("size:", len(t))  # 5
